import * as alien from "@alienplatform/core"

const api = new alien.Container("api")
  .code({ type: "image", image: "ghcr.io/acme/api:3.1.0" })
  .cpu(1)
  .memory("1Gi")
  .port(8080)
  .permissions("api")
  .build()

const scheduler = new alien.Container("scheduler")
  .code({ type: "image", image: "ghcr.io/acme/scheduler:3.1.0" })
  .cpu(1)
  .memory("1Gi")
  .port(9090)
  .permissions("scheduler")
  .build()

const unlisted = new alien.Container("unlisted")
  .code({ type: "image", image: "ghcr.io/acme/unlisted:1.0.0" })
  .cpu(1)
  .memory("1Gi")
  .port(7070)
  .permissions("unlisted")
  .build()

export default new alien.Stack("acme-dynamic-images")
  .platforms(["aws"])
  .add(api, "live")
  .add(scheduler, "live")
  .add(unlisted, "live")
  .permissions({ profiles: { api: {}, scheduler: {}, unlisted: {} } })
  .dynamicContainerImageResources(["api", "scheduler"])
  .build()
